<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\Holder\ConsentPurposeKeyAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the ConsentPurposeKeyAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class ConsentPurposeKeyAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getKey returns null on a freshly created holder.
     */
    public function testKeyNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithConsentPurposeKeyAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isKeyAssigned());
        $this->assertNull($holder->getKey());
    }
}
class ImplWithConsentPurposeKeyAttributeHolderUnitTest
{
    use ConsentPurposeKeyAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedKeyRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultKey();
    }
}
